/** A live cell's position on an unbounded grid, as `[x, y]`. */
export type Cell = [number, number];

const key = (x: number, y: number): string => `${x},${y}`;

const neighbors = (x: number, y: number): Cell[] => {
  const result: Cell[] = [];
  for (let dx = -1; dx <= 1; dx++) {
    for (let dy = -1; dy <= 1; dy++) {
      if (dx !== 0 || dy !== 0) result.push([x + dx, y + dy]);
    }
  }
  return result;
};

/**
 * Tallies, for every cell adjacent to at least one live cell, how many live
 * neighbors it has. Cells absent from the tally have zero live neighbors and
 * so can never be alive next generation.
 */
const countLiveNeighbors = (cells: Cell[]): Map<string, [Cell, number]> => {
  const tally = new Map<string, [Cell, number]>();
  for (const [x, y] of cells) {
    for (const [nx, ny] of neighbors(x, y)) {
      const neighborKey = key(nx, ny);
      const [, count] = tally.get(neighborKey) ?? [[nx, ny], 0];
      tally.set(neighborKey, [[nx, ny], count + 1]);
    }
  }
  return tally;
};

export function nextGeneration(cells: Cell[]): Cell[] {
  const living = new Set(cells.map(([x, y]) => key(x, y)));

  const nextCells: Cell[] = [];
  for (const [cellKey, [cell, count]] of countLiveNeighbors(cells)) {
    const isAlive = living.has(cellKey);
    if (count === 3 || (isAlive && count === 2)) nextCells.push(cell);
  }
  return nextCells;
}
